(()=>{
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),mini=document.getElementById('minimap'),mctx=mini.getContext('2d');
const W=50,H=38,T=48,worldSeed=74123;let seed=worldSeed;const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};
const terrain=[],trees=[],rocks=[],slimes=[];for(let y=0;y<H;y++){terrain[y]=[];for(let x=0;x<W;x++){let n=rand();terrain[y][x]=n<.13?1:n>.96?2:0}}
// A winding stream and the little settlement at its edge.
for(let y=0;y<H;y++){let x=Math.round(24+Math.sin(y*.28)*2);for(let dx=-1;dx<=1;dx++)if(x+dx>=0)terrain[y][x+dx]=3;terrain[y][x-2]=2;terrain[y][x+2]=2}
const village={x:10,y:13},elder={x:10.1,y:10.2},portal={x:43,y:19};
// Keep the first clearing open, then seed a dense blocky forest around it.
for(let y=0;y<H;y++)for(let x=0;x<W;x++){if(x<1||y<1||x>W-2||y>H-2)continue;let dx=x-village.x,dy=y-village.y;if(Math.hypot(dx,dy)<6||Math.hypot(x-portal.x,y-portal.y)<4)continue;if(terrain[y][x]===3)continue;let r=rand();if(r<.12&&!(x>8&&x<15&&y>9&&y<17))trees.push({x:x+.5,y:y+.5,kind:rand()>.82?'pine':'broad'});else if(r<.145)rocks.push({x:x+.5,y:y+.5,kind:rand()>.55?'ore':'stone',taken:false})}
const slimePlaces=[[17,8],[20,19],[15,26],[31,8],[35,25],[40,14],[28,30],[7,29]];for(let i=0;i<slimePlaces.length;i++){let [x,y]=slimePlaces[i];slimes.push({x:x+.5,y:y+.5,homeX:x+.5,homeY:y+.5,hp:2,max:2,alive:true,hit:0,attack:0,phase:rand()*8,variant:i%3})}
const player={x:10.6,y:13.9,faceX:0,faceY:-1,hp:100,max:100,level:1,xp:0,coins:12,potions:2,attack:0,invuln:0,swing:0,hitFlash:0};
let questAccepted=false,kills=0,questDone=false,gateOpen=false,gameStarted=false,paused=false,elapsed=0,toastTimer=0,move={up:false,down:false,left:false,right:false},selected=1,muted=true;const keys=new Set();
const $=id=>document.getElementById(id);function toast(msg){const el=$('toast');el.textContent=msg;el.classList.add('show');toastTimer=2.2}function setSelected(n){selected=n;document.querySelectorAll('.slot').forEach(el=>el.classList.toggle('selected',+el.dataset.slot===n))}function distance(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}
function isSolid(x,y){if(x<.6||y<.6||x>W-.6||y>H-.6)return true;let tx=Math.floor(x),ty=Math.floor(y);if(terrain[ty]?.[tx]===3)return true;for(const t of trees)if(Math.abs(t.x-x)<.43&&Math.abs(t.y-y)<.43)return true; // village buildings
if(x>7.5&&x<12.5&&y>7.1&&y<9.5)return true;if(x>6.2&&x<8.5&&y>11&&y<13)return true;if(x>12.2&&x<14.2&&y>12&&y<14)return true;return false}
function movePlayer(dx,dy,dt){let speed=3.15;if(dx&&dy){dx*=.707;dy*=.707}const nx=player.x+dx*speed*dt,ny=player.y+dy*speed*dt;if(dx){if(!isSolid(nx,player.y))player.x=nx}if(dy){if(!isSolid(player.x,ny))player.y=ny}if(dx||dy){player.faceX=dx;player.faceY=dy}}
function nearestInteract(){let n=distance(player,elder);if(n<1.6)return 'elder';for(const r of rocks)if(!r.taken&&distance(player,r)<1.25)return 'rock';if(distance(player,portal)<2)return 'portal';return null}
function doInteract(){let n=nearestInteract();if(n==='elder'){if(!questAccepted){showDialog('The woods are restless.','Little green things have crept from the old ruins. Clear three slimes and I’ll open the way to the Sunstone Shrine.','I’LL TAKE THE QUEST');}else if(questDone){toast('Elder Rowan: Wildwood owes you its life.');}else toast('Elder Rowan: The old ruins lie east, beyond the stream.');}else if(n==='portal'){if(gateOpen){if(!questDone){questDone=true;showWin()}else toast('The Sunstone Shrine hums warmly.')}else toast('The shrine gate is sealed. Help Elder Rowan first.')}else if(n==='rock'){const r=rocks.find(o=>!o.taken&&distance(player,o)<1.25);if(r){r.taken=true;player.coins+=r.kind==='ore'?4:2;updateUI();toast(r.kind==='ore'?'Copper ore found · +4 coins':'Stone gathered · +2 coins')}}}
function showDialog(title,text,button){$('dialogTitle').textContent=title;$('dialogText').textContent=text;$('dialogOverlay').classList.remove('hidden');$('dialogClose').textContent=button;paused=true}
$('dialogClose').onclick=()=>{$('dialogOverlay').classList.add('hidden');paused=false;if(!questAccepted){questAccepted=true;toast('Quest accepted: A Green Menace')}};$('dialogDismiss').onclick=()=>{$('dialogOverlay').classList.add('hidden');paused=false};function showWin(){$('winOverlay').classList.remove('hidden');paused=true}$('winContinue').onclick=()=>{$('winOverlay').classList.add('hidden');paused=false};
$('startBtn').onclick=()=>{$('startOverlay').classList.add('hidden');gameStarted=true;toast('Find Elder Rowan near the village well · Press E')};$('helpBtn').onclick=()=>{paused=true;$('helpOverlay').classList.remove('hidden')};$('helpClose').onclick=()=>{$('helpOverlay').classList.add('hidden');paused=false};$('soundBtn').onclick=()=>{muted=!muted;$('soundBtn').textContent=muted?'♫':'♪';toast(muted?'Sound effects off':'Sound effects on')};
function addXP(n){player.xp+=n;while(player.xp>=50){player.xp-=50;player.level++;player.max+=10;player.hp=Math.min(player.max,player.hp+30);$('levelPop').classList.remove('visible');void $('levelPop').offsetWidth;$('levelPop').classList.add('visible');toast('Level up! You are now level '+player.level)}}
function attack(){if(!gameStarted||paused||player.attack>0)return;if(selected===3){drinkPotion();return}if(selected===2){toast('Your pickaxe is for mining.');return}player.attack=.42;player.swing=.28;let target=null,best=1.38;for(const s of slimes){if(!s.alive)continue;const dx=s.x-player.x,dy=s.y-player.y,d=Math.hypot(dx,dy);if(d<best&&(dx*player.faceX+dy*player.faceY)>-.35){best=d;target=s}}if(target){target.hp--;target.hit=.22;target.x+=player.faceX*.22;target.y+=player.faceY*.22;if(target.hp<=0){target.alive=false;player.coins+=3+Math.floor(rand()*5);addXP(15);if(questAccepted&&!questDone){kills++;if(kills>=3){questDone=true;gateOpen=true;toast('Three slimes defeated! The shrine gate is open.')}else toast('Slime defeated · '+kills+' / 3 · +15 XP')}else toast('Slime defeated · +15 XP');updateUI()}}}
function drinkPotion(){if(player.potions<1){toast('No potions left.');return}if(player.hp>=player.max){toast('Your health is already full.');return}player.potions--;player.hp=Math.min(player.max,player.hp+40);updateUI();toast('Potion used · +40 health')}
function updateUI(){let hp=Math.max(0,Math.ceil(player.hp/10));$('hearts').innerHTML=Array.from({length:10},(_,i)=>`<span class="heart ${i>=hp?'empty':''}">♥</span>`).join('');$('hpText').textContent=`${Math.ceil(player.hp)} / ${player.max}`;$('levelBadge').textContent=player.level;$('levelText').textContent=String(player.level).padStart(2,'0');$('xpProgress').textContent=player.xp;$('xpBar').style.width=(player.xp/50*100)+'%';$('coinCount').textContent=player.coins;$('xpCount').textContent=player.xp;$('potionCount').textContent=player.potions;$('questCount').textContent=`${Math.min(kills,3)} / 3`;$('questFill').style.width=(Math.min(kills,3)/3*100)+'%';$('questTitle').textContent=questDone?'THE SUNSTONE SHRINE':'A GREEN MENACE';$('questDescription').textContent=questDone?'The way is open. Reach the shrine beyond the eastern stream.':'Clear the slimes from the old forest. Elder Rowan is waiting near the well.';$('questProgressLabel').textContent=questAccepted?'SLIMES DEFEATED':'QUEST START';if(!questAccepted){$('questCount').textContent='TALK TO ROWAN';$('questFill').style.width='0%'}$('questFill').style.background=questDone?'#a9d68b':''}
function drawTile(x,y,tx,ty){const type=terrain[ty]?.[tx]??0;const shade=((tx*17+ty*31)%5);let base=['#456f48','#4d7447','#52784a'][shade%3];if(type===1)base='#476b42';if(type===2)base='#55774a';if(type===3)base='#397c83';ctx.fillStyle=base;ctx.fillRect(x,y,T+1,T+1);ctx.fillStyle=type===3?'#5ea0a0':type===1?'#5a8150':'#638553';ctx.fillRect(x+1,y+1,T-2,3);if(type===3){ctx.fillStyle='#78b3aa';ctx.fillRect(x+((tx+ty)%3)*11+4,y+11,8,2);ctx.fillRect(x+((tx*2+ty)%4)*9+8,y+34,5,2)}else{ctx.fillStyle=type===1?'#3f623e':'#426a43';ctx.fillRect(x+2,y+T-4,T-3,3);let r=(tx*13+ty*19)%31;if(r<5){ctx.fillStyle=r===2?'#d3bd77':r===3?'#a7986e':'#73925a';ctx.fillRect(x+8+r,y+15+(r*7)%23,2,2)}}}
function block(x,y,w,h,top,side){ctx.fillStyle='#0004';ctx.fillRect(x+3,y+h-2,w,h*.24);ctx.fillStyle=side;ctx.fillRect(x,y+h-5,w,6);ctx.fillStyle=top;ctx.fillRect(x,y,w,h-6);ctx.fillStyle='#ffffff16';ctx.fillRect(x,y,w,3);ctx.fillStyle='#0002';ctx.fillRect(x+w-3,y,3,h)}
function drawTree(t,sx,sy){const x=sx*T,y=sy*T;ctx.fillStyle='#182a1c66';ctx.fillRect(x-14,y+9,36,13);ctx.fillStyle='#65472f';ctx.fillRect(x-5,y-2,11,26);ctx.fillStyle='#795638';ctx.fillRect(x-3,y,3,18);if(t.kind==='pine'){block(x-15,y-20,29,25,'#4e8050','#355a3b');block(x-11,y-34,22,22,'#63945a','#3e6c45');block(x-6,y-45,13,16,'#78a861','#4c7b4c')}else{block(x-16,y-22,33,30,'#52834e','#345c3c');block(x-9,y-34,25,20,'#68975a','#3f6b43');ctx.fillStyle='#85a761';ctx.fillRect(x-10,y-31,7,3);ctx.fillRect(x+6,y-20,6,3)}ctx.fillStyle='#283c2b';ctx.fillRect(x-11,y+17,25,4)}
function drawHouse(x,y,roof='#804c3b'){let px=x*T,py=y*T;ctx.fillStyle='#253128';ctx.fillRect(px-5,py+27,62,12);ctx.fillStyle='#c0a475';ctx.fillRect(px,py+2,50,31);ctx.fillStyle='#e0c58f';ctx.fillRect(px+3,py+4,44,26);ctx.fillStyle='#a57e59';ctx.fillRect(px+4,py+26,42,6);ctx.fillStyle=roof;ctx.fillRect(px-5,py-5,60,15);ctx.fillRect(px+2,py-9,44,6);ctx.fillStyle='#ad7151';ctx.fillRect(px+20,py+17,12,16);ctx.fillStyle='#e3cb8e';ctx.fillRect(px+23,py+19,3,3);ctx.fillStyle='#3d5849';ctx.fillRect(px+7,py+11,9,8);ctx.fillRect(px+36,py+11,8,8)}
function drawVillage(){drawHouse(8.2,7.3,'#76513e');drawHouse(11.9,11.1,'#6d5641'); // well
let x=9.8*T,y=13.1*T;ctx.fillStyle='#344d45';ctx.fillRect(x-2,y-2,38,27);ctx.fillStyle='#b9aa7c';ctx.fillRect(x,y,34,19);ctx.fillStyle='#437b78';ctx.fillRect(x+4,y+4,26,10);ctx.fillStyle='#d3bd83';ctx.fillRect(x-2,y-4,38,5);ctx.fillStyle='#654a37';ctx.fillRect(x+5,y-11,3,8);ctx.fillRect(x+25,y-11,3,8);ctx.fillRect(x+5,y-12,23,3);
// little fence + crop patch
ctx.fillStyle='#9d8055';for(let i=0;i<5;i++){ctx.fillRect(6.7*T+i*10,15.9*T,3,7);ctx.fillRect(6.7*T+i*10,16.3*T,9,2)}ctx.fillStyle='#8fa45d';for(let i=0;i<5;i++){ctx.fillRect(7.5*T+i*6,14.4*T,2,6);ctx.fillRect(8*T+i*5,14.7*T,2,5)}
}
function drawElder(sx,sy){let x=sx*T,y=sy*T;ctx.fillStyle='#0005';ctx.fillRect(x-11,y+13,22,6);ctx.fillStyle='#b9a875';ctx.fillRect(x-8,y-5,16,19);ctx.fillStyle='#719276';ctx.fillRect(x-10,y+3,20,12);ctx.fillStyle='#e0bf91';ctx.fillRect(x-6,y-13,12,11);ctx.fillStyle='#ded0a5';ctx.fillRect(x-8,y-15,16,5);ctx.fillStyle='#574d38';ctx.fillRect(x-6,y-6,3,2);ctx.fillRect(x+3,y-6,3,2);ctx.fillStyle='#6b5138';ctx.fillRect(x+10,y-2,3,19);ctx.fillStyle='#dfd190';ctx.fillRect(x-12,y-25,24,8);ctx.font='10px sans-serif';ctx.textAlign='center';ctx.fillText('✦',x,y-28)}
function drawPlayer(){let x=canvas.width/2,y=canvas.height/2;let d=player.faceY>0?'down':player.faceY<0?'up':player.faceX>0?'right':'left';const bob=(Math.sin(elapsed*10)*1.5)*(move.up||move.down||move.left||move.right?1:0);ctx.fillStyle='#18271b88';ctx.fillRect(x-13,y+15,27,8); // shadow
ctx.fillStyle='#664630';ctx.fillRect(x-10,y-18+bob,20,9);ctx.fillRect(x-13,y-14+bob,26,4);ctx.fillStyle='#c89362';ctx.fillRect(x-8,y-12+bob,16,16);ctx.fillStyle='#322d25';if(d==='down'){ctx.fillRect(x-5,y-5+bob,3,3);ctx.fillRect(x+3,y-5+bob,3,3)}else if(d==='left')ctx.fillRect(x-7,y-6+bob,3,3);else if(d==='right')ctx.fillRect(x+4,y-6+bob,3,3);else ctx.fillRect(x-4,y-9+bob,8,3);ctx.fillStyle='#527b50';ctx.fillRect(x-11,y+3+bob,22,15);ctx.fillStyle='#3d6345';ctx.fillRect(x-8,y+16+bob,6,8);ctx.fillRect(x+2,y+16+bob,6,8);ctx.fillStyle='#b18b5d';ctx.fillRect(x-14,y+5+bob,4,12);ctx.fillRect(x+10,y+5+bob,4,12);
// wooden blade and active swing arc
if(player.swing>0){ctx.save();ctx.translate(x,y);let angle=Math.atan2(player.faceY,player.faceX);ctx.strokeStyle='#fff0a5aa';ctx.lineWidth=4;ctx.beginPath();ctx.arc(0,0,32,angle-.95,angle+.95);ctx.stroke();ctx.restore()}
let ax=x+player.faceX*14+player.faceY*8,ay=y+player.faceY*14-player.faceX*8;ctx.save();ctx.translate(ax,ay);ctx.rotate(Math.atan2(player.faceY,player.faceX)+Math.PI/4);ctx.fillStyle='#d4c7a0';ctx.fillRect(-2,-18,5,23);ctx.fillStyle='#a87645';ctx.fillRect(-3,4,7,12);ctx.fillStyle='#624b31';ctx.fillRect(-5,1,11,3);ctx.restore();if(player.invuln>0&&Math.floor(elapsed*18)%2===0){ctx.fillStyle='#ffffff77';ctx.fillRect(x-13,y-18,26,42)}}
function drawSlime(s){if(!s.alive)return;let x=(s.x-camX)*T+canvas.width/2,y=(s.y-camY)*T+canvas.height/2;let leap=Math.sin(elapsed*4+s.phase);let h=17+Math.max(0,leap)*9;ctx.fillStyle='#10221970';ctx.beginPath();ctx.ellipse(x,y+13,15,5,0,0,Math.PI*2);ctx.fill();let colors=['#73c986','#80c89d','#a0ba6c'];ctx.fillStyle=s.hit>0?'#e7f3b4':colors[s.variant];ctx.beginPath();ctx.moveTo(x-14,y+9);ctx.lineTo(x-13,y-h*.55);ctx.quadraticCurveTo(x,y-h-3,x+13,y-h*.55);ctx.lineTo(x+14,y+9);ctx.quadraticCurveTo(x,y+15,x-14,y+9);ctx.fill();ctx.fillStyle='#477853';ctx.fillRect(x-8,y-h*.47,4,4);ctx.fillRect(x+4,y-h*.47,4,4);ctx.fillStyle='#ddedbc';ctx.fillRect(x-7,y-h*.5,2,2);ctx.fillRect(x+5,y-h*.5,2,2);if(s.hp<s.max){ctx.fillStyle='#17251d';ctx.fillRect(x-12,y-h-9,24,3);ctx.fillStyle='#e17d64';ctx.fillRect(x-11,y-h-8,22*(s.hp/s.max),1)}}
let camX=player.x,camY=player.y;
function drawWorld(){ctx.clearRect(0,0,canvas.width,canvas.height);camX=Math.max(10,Math.min(W-10,player.x));camY=Math.max(7,Math.min(H-7,player.y));const minX=Math.floor(camX-11),maxX=Math.ceil(camX+11),minY=Math.floor(camY-8),maxY=Math.ceil(camY+8);for(let ty=minY;ty<=maxY;ty++)for(let tx=minX;tx<=maxX;tx++){let sx=(tx-camX)*T+canvas.width/2,sy=(ty-camY)*T+canvas.height/2;drawTile(sx,sy,tx,ty)}
// dirt path from village across the wilds
ctx.fillStyle='#a99262';for(let i=0;i<22;i++){let px=14+i,py=Math.round(14+Math.sin(i*.22)*2);if(px<W&&terrain[py]?.[px]!==3){let sx=(px-camX)*T+canvas.width/2,sy=(py-camY)*T+canvas.height/2;ctx.fillRect(sx+7,sy+19,34,12);ctx.fillStyle='#c2a876';ctx.fillRect(sx+13,sy+20,8,2);ctx.fillStyle='#a99262'}}
drawVillage(); // shrine gateway
let gx=portal.x*T,gy=portal.y*T;ctx.fillStyle='#493d2d';ctx.fillRect(gx-22,gy-39,8,58);ctx.fillRect(gx+14,gy-39,8,58);ctx.fillStyle=gateOpen?'#e7cf79':'#665947';ctx.fillRect(gx-18,gy-41,36,8);ctx.fillStyle=gateOpen?'#9edb9a':'#392f2a';ctx.fillRect(gx-14,gy-31,28,40);ctx.fillStyle=gateOpen?'#ebd989':'#987a4e';ctx.fillRect(gx-19,gy+9,38,7);if(gateOpen){ctx.globalAlpha=.35+Math.sin(elapsed*3)*.1;ctx.fillStyle='#ccdf8c';ctx.fillRect(gx-13,gy-29,26,37);ctx.globalAlpha=1}else{ctx.fillStyle='#d7bd75';ctx.fillRect(gx-4,gy-13,8,8)}
// sort sprites by foot position for a layered top-down effect
let actors=[...trees.map(t=>({y:t.y,type:'tree',o:t})),...slimes.filter(s=>s.alive).map(s=>({y:s.y,type:'slime',o:s})),{y:elder.y,type:'elder'},{y:player.y,type:'player'}].sort((a,b)=>a.y-b.y);for(const a of actors){if(a.type==='tree')drawTree(a.o,a.o.x-camX+canvas.width/(2*T),a.o.y-camY+canvas.height/(2*T));else if(a.type==='slime')drawSlime(a.o);else if(a.type==='elder')drawElder(a.o.x-camX+canvas.width/(2*T),a.o.y-camY+canvas.height/(2*T));else drawPlayer()}
for(const r of rocks){if(r.taken)continue;let x=(r.x-camX)*T+canvas.width/2,y=(r.y-camY)*T+canvas.height/2;ctx.fillStyle='#0004';ctx.fillRect(x-9,y+7,20,6);ctx.fillStyle=r.kind==='ore'?'#777f66':'#858e7a';ctx.fillRect(x-8,y-3,15,12);ctx.fillStyle=r.kind==='ore'?'#b68d5d':'#abb39a';ctx.fillRect(x-5,y-5,9,5);if(r.kind==='ore'){ctx.fillStyle='#d8b26b';ctx.fillRect(x-2,y-2,4,3)}}
// World border edge fade
